exercise.solution:
ALTER TABLE tasks
ADD COLUMN priority TEXT NOT NULL DEFAULT 'normal'
CHECK (priority IN ('low', 'normal', 'high'));

CREATE TABLE tags (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL UNIQUE
);

CREATE TABLE task_tags (
  task_id INTEGER NOT NULL,
  tag_id INTEGER NOT NULL,
  PRIMARY KEY (task_id, tag_id),
  FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE,
  FOREIGN KEY (tag_id) REFERENCES tags(id) ON DELETE CASCADE
);

INSERT INTO tags (name) VALUES
  ('work'),
  ('home');

tests.code:
const rows = await query(`SELECT id, title, done, priority
FROM tasks
ORDER BY id;`);

if (rows.length !== 4) throw new Error(`Expected 4 tasks, got ${rows.length}`);

for (const row of rows) {
  if (row.priority !== 'normal') {
    throw new Error(`Task ${row.id} should have priority normal`);
  }
}

return true;

let failed = false;

try {
  await query(`INSERT INTO tasks (title, done, priority)
  VALUES ('Hibás prioritás', 0, 'urgent');`);
} catch (error) {
  failed = true;
}

if (!failed) throw new Error('Expected the priority CHECK constraint to reject urgent');

return true;

const rows = await query(`SELECT name
FROM tags
ORDER BY name;`);

if (rows.length !== 2) throw new Error(`Expected 2 tags, got ${rows.length}`);
if (rows[0].name !== 'home') throw new Error('Expected home tag');
if (rows[1].name !== 'work') throw new Error('Expected work tag');

return true;

let failed = false;

try {
  await query(`INSERT INTO task_tags (task_id, tag_id)
  VALUES (1, 1), (1, 1);`);
} catch (error) {
  failed = true;
}

if (!failed) throw new Error('Expected duplicate task-tag pair to be rejected');

return true;

await query(`INSERT INTO task_tags (task_id, tag_id)
VALUES (1, 1), (1, 2);`);

await query(`DELETE FROM tasks WHERE id = 1;`);

const rows = await query(`SELECT *
FROM task_tags
WHERE task_id = 1;`);

if (rows.length !== 0) {
  throw new Error('Expected ON DELETE CASCADE to remove task_tags links');
}

return true;
